INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7432539, 1174112, 114285, '<td valign="top">Gorgeous!! One of my faves!! Simple and elegant.</td>', 'Gorgeous!! One of my faves!! Simple and elegant.', '2016-01-28 02:30:06.000000', NULL, 1),
(7432540, 1174343, 114285, '<td valign="top">I''m mesmerised ~ thankyou!<br/> <br/>Top 2.</td>', 'I''m mesmerised ~ thankyou! Top 2.', '2016-01-28 02:32:42.000000', NULL, 1),
(7432541, 1174365, 114285, '<td valign="top">I would of cropped the bottom third out, love the top half.</td>', 'I would of cropped the bottom third out, love the top half.', '2016-01-28 02:33:58.000000', NULL, 1),
(7432542, 1174423, 114285, '<td valign="top">Love the purple, very cool!</td>', 'Love the purple, very cool!', '2016-01-28 02:35:36.000000', NULL, 1),
(7432543, 1174389, 114285, '<td valign="top">Really love this one, but and there''s a but,...there is quite a bit of banding on the top left hand side. I would of probably cropped the sky out and about half of the right hand side as it doesn''t add anything to the image. As for the water and house it''s quite moody and mystical.</td>', 'Really love this one, but and there''s a but,...there is quite a bit of banding on the top left hand side. I would of probably cropped the sky out and about half of the right hand side as it doesn''t add anything to the image. As for the water and house it''s quite moody and mystical.', '2016-01-28 02:38:22.000000', NULL, 1),
(7432544, 1174397, 114285, '<td valign="top">I can see this on a wall in a new display home! Top five.</td>', 'I can see this on a wall in a new display home! Top five.', '2016-01-28 02:38:52.000000', NULL, 1),
(7432546, 1174403, 37858, '<td valign="top">Ribbon IMHO.  I''d love to see this in color too. I could see this on a wall, about 5 or 6 feet long.</td>', 'Ribbon IMHO.  I''d love to see this in color too. I could see this on a wall, about 5 or 6 feet long.', '2016-01-28 02:44:00.000000', NULL, 1),
(7432547, 1174126, 37858, '<td valign="top">Ribbon IMHO.  Very mellow, peaceful and quiet.</td>', 'Ribbon IMHO.  Very mellow, peaceful and quiet.', '2016-01-28 02:44:37.000000', NULL, 1),
